{
  "steps": [
    {
      "id": 1,
      "description": "Update the package list to ensure the latest versions are available.",
      "command_hint": "apt-get update"
    },
    {
      "id": 2,
      "description": "Install ufw (Uncomplicated Firewall) to manage network traffic.",
      "command_hint": "apt-get install -y ufw"
    },
    {
      "id": 3,
      "description": "Set the default policy to deny all incoming traffic.",
      "command_hint": "ufw default deny incoming"
    },
    {
      "id": 4,
      "description": "Set the default policy to allow all outgoing traffic.",
      "command_hint": "ufw default allow outgoing"
    },
    {
      "id": 5,
      "description": "Allow SSH traffic to ensure remote administration is possible.",
      "command_hint": "ufw allow ssh"
    },
    {
      "id": 6,
      "description": "Allow HTTP traffic for web services.",
      "command_hint": "ufw allow http"
    },
    {
      "id": 7,
      "description": "Enable ufw to start enforcing the firewall rules.",
      "command_hint": "ufw enable"
    },
    {
      "id": 8,
      "description": "Verify the status of ufw to ensure it is active and rules are applied.",
      "command_hint": "ufw status verbose"
    },
    {
      "id": 9,
      "description": "Check the listening ports to confirm the firewall is filtering traffic.",
      "command_hint": "ss -tulnp"
    },
    {
      "id": 10,
      "description": "Ensure the SSH service is running and accessible.",
      "command_hint": "service ssh status"
    },
    {
      "id": 11,
      "description": "Ensure the nginx service is running and accessible if installed.",
      "command_hint": "service nginx status"
    },
    {
      "id": 12,
      "description": "Restart the SSH service to ensure it is properly configured with the firewall.",
      "command_hint": "service ssh restart"
    },
    {
      "id": 13,
      "description": "Restart the nginx service to ensure it is properly configured with the firewall.",
      "command_hint": "service nginx restart"
    },
    {
      "id": 14,
      "description": "Verify that the firewall rules are correctly applied and services are accessible.",
      "command_hint": "ufw status numbered"
    },
    {
      "id": 15,
      "description": "Confirm the system is secure by checking the firewall status and listening ports.",
      "command_hint": "echo REMEDIATION_COMPLETE"
    }
  ]
}
